import {
    Component
} from '@angular/core';
import {
    ChangeDetectorRef
} from '@angular/core';
import {
    ApperyioHelperService
} from '../scripts/apperyio/apperyio_helper';
import {
    ApperyioMappingHelperService
} from '../scripts/apperyio/apperyio_mapping_helper';
import {
    NavController
} from '@ionic/angular';
import {
    ExportedClass as ApperyTTS
} from '../scripts/custom/ApperyTTS';
import {
    ExportedClass as ApperySpeech
} from '../scripts/custom/ApperySpeech';
import {
    $aio_empty_object
} from '../scripts/interfaces';
import {
    ViewChild
} from '@angular/core';
@Component({
    standalone: false,
    templateUrl: 'play.html',
    selector: 'page-play',
    styleUrls: ['play.css', 'play.scss']
})
export class play {
    public aioScreenName = "play";
    public successSound: any;
    public failedSound: any;
    public text: any;
    public dictionary: any;
    public pair: any;
    public mode: any;
    public stopped: any;
    public time: any;
    public correctAnswer: any;
    public stopPlayFlag: any;
    public successCount: any;
    public failedCount: any;
    public i: any;
    public beep: any;
    public words: any;
    public $a: ApperyioHelperService;
    public $v: {
        [name: string]: any
    };
    public aioChangeDetector: ChangeDetectorRef;
    public currentItem: any = null;
    private _aioPrevNoBounce = false;
    @ViewChild('_aio_content') _aio_content;
    public mappingData: any = {};
    public __getMapping(_currentItem, property, defaultValue, isVariable?, isSelected?) {
        return this.$aio_mappingHelper.getMapping(this.mappingData, _currentItem, property, defaultValue, isVariable, isSelected);
    }
    public __isPropertyInMapping(_currentItem, property) {
        return this.$aio_mappingHelper.isPropertyInMapping(this.mappingData, _currentItem, property);
    }
    public __setMapping(data: any = {}, keyName: string, propName?: string): void {
        const changes = data.detail || {};
        if (propName) {
            this.mappingData = this.$aio_mappingHelper.updateData(this.mappingData, [keyName], changes[propName]);
        } else {
            this.mappingData = this.$aio_mappingHelper.updateData(this.mappingData, [keyName], changes.value);
        }
        this.$aio_changeDetector.detectChanges();
    }
    public __bindedMethods: any = {};
    async ionViewWillEnter(): Promise < any > {
        try {
            await this.$v?.ionViewWillEnter?.call?.(this);
        } catch (e) {
            console.log(e);
        }
        document.documentElement.classList.toggle("aio-no-bounce", false);
        let id = this.$a.getRouteParam("id");
        this.dictionary = await this.$a.db.getById('dictionaries', id);
        this.stopPlayFlag = false;
        this.successCount = 0;
        this.failedCount = 0;
        this.successCount = this.dictionary.knownWords || 0;
        this.i = 0;
        this.words = this.$a._.cloneDeep(this.dictionary.words);
        this.words = this.$a._.shuffle(this.words);
        await this.play();
        window.currentScreen = this;
    }
    playSound(sound): any {
        return new Promise(resolve => {
            // if (window.cordova) {
            //     window.plugins.NativeAudio.play('success', resolve, (e) => alert(JSON.stringify(e)));
            // } else {
            const audio = new Audio(sound);
            audio.play().catch(resolve);;
            audio.addEventListener?.("ended", () => {
                resolve(true);
            });
            audio.onended = () => {
                resolve(true);
            };
            // Reject if an error occurs (e.g., invalid base64 or format)
            audio.onerror = (err) => {
                resolve(true);
            };
            //    }
        });
    }
    async stop(): Promise < any > {
        if (this.stopped) return;
        this.stopped = true;
        this.text = await this.speech.stop();
        this.$a.closeModal(this.text);
    }
    recognize(): any {
        return new Promise((resolve, reject) => {
            this.stopped = false;
            this.text = this.text || '';
            this.speech.start({
                lang: this.dictionary.to,
                silenceMs: this.time,
                onResult: async (text) => {
                    this.text = text;
                    this.aioChangeDetector.detectChanges();
                    if (this.containsLetters(this.text, this.pair[1])) resolve(true)
                    //            if (this.text?.toUpperCase() == this.pair[1]?.toUpperCase()) resolve(true)  //await this.stop();
                },
                onSilence: () => {
                    resolve(false)
                    //this.stop();
                },
                onFatalError: async (message) => {
                    resolve(false)
                    // await this.$a.alert(message);
                    // this.stop();
                }
            });
        });
    }
    async stopPlay(): Promise < any > {
        this.stopPlayFlag = !this.stopPlayFlag;
        //this.mode = this.stopPlayFlag ? 'stop' : 'recognition';
        // let dictionaryName = 'mydictionary'; 
        // let words = await this.$a.getStorage(dictionaryName);
        if (!this.stopPlayFlag) await this.play();
        // else {
        //     await this.$a.db.save('mydictionary', {
        //         userId: this.$v.user._id,
        //         name: dictionaryName,
        //         words: JSON.stringify(words)
        //     });
        // }
    }
    containsLetters(str, search): any {
        //    const normalize = s => s.toLowerCase().replace(/[^\p{L}]/gu, '');
        return this.normalize(str).includes(this.normalize(search));
    }
    playNote(frequency): any {
        let a = new AudioContext(),
            o = a.createOscillator();
        o.frequency.value = frequency;
        o.connect(a.destination);
        o.start();
        o.stop(a.currentTime + 0.1);
    }
    async back(): Promise < any > {
        this.stopPlayFlag = true;
        let dictionaryName = 'mydictionary';
        await this.$a.setStorage(dictionaryName, this.$v.mydictionary);
        await this.$a.db.save('mydictionary', {
            _id: this.$v.mydictionary._id,
            userId: this.$v.user._id,
            name: dictionaryName,
            words: JSON.stringify(this.$v.mydictionary.words)
        });
        for (let item of this.$v.dictionaries) {
            let count = 0;
            item.knownWords = 0;
            for (let word of item.words) {
                if (this.$v.mydictionary.words[word[0]] >= 3) item.knownWords++;
            }
        }
    }
    async play(): Promise < any > {
        let dictionaryName = 'mydictionary'; // + this.dictionary.from + '-' + this.dictionary.to;
        while (this.i < this.words?.length) {
            if (this.stopPlayFlag) break;
            this.text = '';
            this.correctAnswer = '';
            this.pair = this.dictionary.words[this.i];
            if (this.$v.mydictionary.words[this.pair[0]] >= 3) {
                this.i++;
                continue;
            }
            await this.tts.speak({
                text: this.pair[0],
                locale: this.dictionary.from,
                //        identifier: this.selectedVoice || undefined,
                //        rate: Number(this.rate),
                cancel: true
            });
            if (this.$a.isBrowser() || this.$a.isIOS()) await this.playSound(this.beep);
            //    await this.$a.timeout(100);
            //    this.playNote(500);
            if (this.stopPlayFlag) break;
            this.mode = 'recognition';
            let status = await this.recognize();
            await this.stop();
            this.correctAnswer = this.pair[1];
            if (this.stopPlayFlag) break;
            if (status) {
                this.successCount++;
                if (!this.$v.mydictionary.words[this.pair[0]]) this.$v.mydictionary.words[this.pair[0]] = 0;
                this.$v.mydictionary.words[this.pair[0]]++;
                await this.$a.setStorage(dictionaryName, this.$v.mydictionary);
                await this.playSound(this.successSound)
            } else {
                if (!this.text) this.text = '-';
                this.failedCount++;
                await this.playSound(this.failedSound);
                if (this.stopPlayFlag) break;
                await this.tts.speak({
                    text: this.pair[1],
                    locale: this.dictionary.to,
                    //        identifier: this.selectedVoice || undefined,
                    //        rate: Number(this.rate),
                    cancel: true
                });
                if (this.stopPlayFlag) break;
                if (this.$a.isBrowser() || this.$a.isIOS()) await this.playSound(this.beep);
                if (this.stopPlayFlag) break;
                status = await this.recognize();
                await this.stop();
                await this.playSound(status? this.successSound: this.failedSound);
                await this.$a.timeout(1000);
            }
            this.i++;
        }
        await this.$a.setStorage(dictionaryName, this.$v.mydictionary);
        await this.$a.db.save('mydictionary', {
            _id: this.$v.mydictionary._id,
            userId: this.$v.user._id,
            name: dictionaryName,
            words: JSON.stringify(this.$v.mydictionary.words)
        });
        for (let item of this.$v.dictionaries) {
            let count = 0;
            item.knownWords = 0;
            for (let word of item.words) {
                if (this.$v.mydictionary.words[word[0]] >= 3) item.knownWords++;
            }
        }
        if (this.i >= this.dictionary.words?.length) {
            this.mode = 'finish';
            //    let words = await this.$a.getStorage(dictionaryName);
            //    await this.$a.alertAsync('The dicrionary is finished', 'Info');
            //    this.navCtrl.back();
        }
    }
    normalize(str): any {
        var englishRedundunts = [{
                "red": "i'm",
                "full": "i am"
            },
            {
                "red": "i've",
                "full": "i have"
            },
            {
                "red": "i'll",
                "full": "i will"
            },
            {
                "red": "you're",
                "full": "you are"
            },
            {
                "red": "you've",
                "full": "you have"
            },
            {
                "red": "you'll",
                "full": "you will"
            },
            {
                "red": "he's",
                "full": "he is"
            },
            {
                "red": "he'll",
                "full": "he will"
            },
            {
                "red": "she's",
                "full": "she is"
            },
            {
                "red": "she'll",
                "full": "she will"
            },
            {
                "red": "it's",
                "full": "it is"
            },
            {
                "red": "we're",
                "full": "we are"
            },
            {
                "red": "we've",
                "full": "we have"
            },
            {
                "red": "we'll",
                "full": "we will"
            },
            {
                "red": "they're",
                "full": "they are"
            },
            {
                "red": "they've",
                "full": "they have"
            },
            {
                "red": "they'll",
                "full": "they will"
            },
            {
                "red": "there's",
                "full": "there is"
            },
            {
                "red": "there'll",
                "full": "there will"
            },
            {
                "red": "can't",
                "full": "cannot"
            },
            {
                "red": "couldn't",
                "full": "could not"
            },
            {
                "red": "didn't",
                "full": "did not"
            },
            {
                "red": "doesn't",
                "full": "does not"
            },
            {
                "red": "don't",
                "full": "do not"
            },
            {
                "red": "hadn't",
                "full": "had not"
            },
            {
                "red": "hasn't",
                "full": "has not"
            },
            {
                "red": "isn't",
                "full": "is not"
            },
            {
                "red": "shouldn't",
                "full": "should not"
            },
            {
                "red": "wasn't",
                "full": "was not"
            },
            {
                "red": "weren't",
                "full": "were not"
            },
            {
                "red": "won't",
                "full": "will not"
            },
            {
                "red": "wouldn't",
                "full": "would not"
            }
        ];
        str = str.toLowerCase();
        for (var i in englishRedundunts) {
            str = str.replace(englishRedundunts[i].red, englishRedundunts[i].full);
        }
        //return str.replace(/[^a-zA-Z]+/g, '');
        return str.replace(/[^\p{L}]/gu, '')
    }
    constructor(public Apperyio: ApperyioHelperService, private $aio_mappingHelper: ApperyioMappingHelperService, private $aio_changeDetector: ChangeDetectorRef, public tts: ApperyTTS, public speech: ApperySpeech, public navCtrl: NavController) {
        this.$a = this.Apperyio;
        this.$v = this.Apperyio.vars;
        this.successSound = 'data:audio/wav;base64,';
        this.failedSound = 'data:audio/wav;base64,';
        this.dictionary = {};
        this.pair = {};
        this.mode = 'recognition';
        this.time = 3000;
        this.correctAnswer = '';
        this.stopPlayFlag = false;
        this.successCount = 0;
        this.failedCount = 0;
        this.beep = 'data:audio/wav;base64,';
        this.words = [];
        this.aioChangeDetector = this.$aio_changeDetector;
    }
    ngOnInit() {
        this.Apperyio.setThinScrollIfNeeded();
    }
    ionViewWillLeave() {
        try {
            this.$v?.ionViewWillLeave?.call?.(this);
        } catch (e) {
            console.log(e);
        }
    }
}